import { useState, useEffect } from 'react';
import './styles.css';

interface DataPoint {
  id: number;
  x: number;
  y: number;
  split: 'training' | 'validation' | 'test' | 'none';
}

export default function App() {
  const [trainPct, setTrainPct] = useState(70);
  const [valPct, setValPct] = useState(15);
  const [testPct, setTestPct] = useState(15);
  const [dataPoints, setDataPoints] = useState<DataPoint[]>([]);
  const [isSplit, setIsSplit] = useState(false);
  const [isTrained, setIsTrained] = useState(false);
  const [trainAcc, setTrainAcc] = useState(0);
  const [valAcc, setValAcc] = useState(0);
  const [warning, setWarning] = useState<string | null>(null);

  // Initialize 50 data points
  useEffect(() => {
    const points: DataPoint[] = [];
    for (let i = 0; i < 50; i++) {
      points.push({
        id: i,
        x: 20 + Math.random() * 260,
        y: 20 + Math.random() * 80,
        split: 'none',
      });
    }
    setDataPoints(points);
  }, []);

  const handleTrainChange = (val: number) => {
    const newTrain = val;
    const remaining = 100 - newTrain;
    const newVal = Math.min(valPct, remaining);
    const newTest = remaining - newVal;
    setTrainPct(newTrain);
    setValPct(newVal);
    setTestPct(newTest);
    setIsSplit(false);
    setIsTrained(false);
  };

  const handleValChange = (val: number) => {
    const maxVal = 100 - trainPct;
    const newVal = Math.min(val, maxVal);
    setValPct(newVal);
    setTestPct(maxVal - newVal);
    setIsSplit(false);
    setIsTrained(false);
  };

  const splitData = () => {
    const shuffled = [...dataPoints].sort(() => Math.random() - 0.5);
    const trainCount = Math.floor(shuffled.length * (trainPct / 100));
    const valCount = Math.floor(shuffled.length * (valPct / 100));

    const newPoints = shuffled.map((p, i) => {
      if (i < trainCount) return { ...p, split: 'training' as const };
      if (i < trainCount + valCount) return { ...p, split: 'validation' as const };
      return { ...p, split: 'test' as const };
    });
    setDataPoints(newPoints);
    setIsSplit(true);
    setIsTrained(false);
    setWarning(null);
  };

  const trainModel = () => {
    // Simulate training results based on split
    let tAcc = 0;
    let vAcc = 0;

    if (trainPct < 20) {
      tAcc = 50 + Math.random() * 20;
      vAcc = 40 + Math.random() * 15;
      setWarning('Too little training data! The model can\'t learn enough patterns.');
    } else if (valPct === 0) {
      tAcc = 95 + Math.random() * 4;
      vAcc = 0;
      setWarning('No validation data! You can\'t tell if the model is overfitting.');
    } else if (trainPct > 90) {
      tAcc = 98 + Math.random() * 1.5;
      vAcc = 60 + Math.random() * 10;
      setWarning('Overfitting detected! Training accuracy is high but validation is low.');
    } else {
      tAcc = 85 + Math.random() * 10;
      vAcc = 80 + Math.random() * 10;
      setWarning(null);
    }

    setTrainAcc(tAcc);
    setValAcc(vAcc);
    setIsTrained(true);
  };

  const reset = () => {
    setDataPoints(dataPoints.map(p => ({ ...p, split: 'none' })));
    setIsSplit(false);
    setIsTrained(false);
    setWarning(null);
    setTrainPct(70);
    setValPct(15);
    setTestPct(15);
  };

  const getColor = (split: string) => {
    switch (split) {
      case 'training': return '#3B82F6';
      case 'validation': return '#F59E0B';
      case 'test': return '#10B981';
      default: return '#94A3B8';
    }
  };

  const getTargetY = (split: string, originalY: number) => {
    if (!isSplit) return originalY;
    switch (split) {
      case 'training': return 30 + (originalY / 100) * 40;
      case 'validation': return 80 + (originalY / 100) * 30;
      case 'test': return 130 + (originalY / 100) * 30;
      default: return originalY;
    }
  };

  return (
    <div className="app">
      <h1>Data Split Simulator</h1>
      <p className="intro">Adjust the sliders to see how different data splits affect model performance.</p>

      <div className="sliders">
        <div className="slider-group">
          <label>Training: {trainPct}%</label>
          <input type="range" min="10" max="95" value={trainPct} onChange={e => handleTrainChange(Number(e.target.value))} />
          <span className="color-dot training"></span>
        </div>
        <div className="slider-group">
          <label>Validation: {valPct}%</label>
          <input type="range" min="0" max="40" value={valPct} onChange={e => handleValChange(Number(e.target.value))} />
          <span className="color-dot validation"></span>
        </div>
        <div className="slider-group">
          <label>Test: {testPct}%</label>
          <div className="test-label">(auto-calculated)</div>
          <span className="color-dot test"></span>
        </div>
      </div>

      <div className="controls">
        <button onClick={splitData} className="primary">Split Data</button>
        <button onClick={trainModel} disabled={!isSplit}>Train Model</button>
        <button onClick={reset}>Reset</button>
      </div>

      <div className="visualization">
        <svg viewBox="0 0 300 180" className="data-viz">
          {/* Bucket labels */}
          {isSplit && (
            <>
              <text x="10" y="35" fontSize="10" fill="#3B82F6" fontWeight="500">Training ({trainPct}%)</text>
              <text x="10" y="85" fontSize="10" fill="#F59E0B" fontWeight="500">Validation ({valPct}%)</text>
              <text x="10" y="135" fontSize="10" fill="#10B981" fontWeight="500">Test ({testPct}%)</text>
              <line x1="0" y1="65" x2="300" y2="65" stroke="#E2E8F0" strokeDasharray="4" />
              <line x1="0" y1="115" x2="300" y2="115" stroke="#E2E8F0" strokeDasharray="4" />
            </>
          )}
          {/* Data points */}
          {dataPoints.map(point => (
            <circle
              key={point.id}
              cx={point.x}
              cy={getTargetY(point.split, point.y)}
              r="5"
              fill={getColor(point.split)}
              style={{ transition: 'all 0.6s ease-out' }}
            />
          ))}
        </svg>
      </div>

      {isTrained && (
        <div className="results">
          <h3>Training Results</h3>
          <div className="accuracy-bars">
            <div className="bar-group">
              <div className="bar-label">Training Accuracy</div>
              <div className="bar-container">
                <div className="bar training" style={{ width: `${trainAcc}%` }}></div>
              </div>
              <div className="bar-value">{trainAcc.toFixed(1)}%</div>
            </div>
            <div className="bar-group">
              <div className="bar-label">Validation Accuracy</div>
              <div className="bar-container">
                <div className="bar validation" style={{ width: `${valAcc}%` }}></div>
              </div>
              <div className="bar-value">{valPct > 0 ? `${valAcc.toFixed(1)}%` : 'N/A'}</div>
            </div>
          </div>
          {warning && <div className="warning">{warning}</div>}
        </div>
      )}

      <div className="tips">
        <h3>Try these experiments:</h3>
        <ul>
          <li><strong>95/0/5 split:</strong> See what happens without validation data</li>
          <li><strong>20/40/40 split:</strong> Too little training data</li>
          <li><strong>70/15/15 split:</strong> A balanced approach</li>
        </ul>
      </div>

      <div className="reflection">
        <h3>Reflection</h3>
        <ul>
          <li>What happened when you gave the model very little training data?</li>
          <li>What's the danger of skipping validation data entirely?</li>
          <li>If training accuracy is 98% but validation is 60%, what's happening?</li>
        </ul>
      </div>
    </div>
  );
}

