body { font-family: system-ui, -apple-system, sans-serif; background: #f8fafc; margin: 0; padding: 16px; }
.app { max-width: 600px; margin: 0 auto; }
h1 { font-size: 1.5rem; color: #1e293b; margin-bottom: 0.5rem; }
.intro { color: #64748b; margin-bottom: 1.5rem; font-size: 0.9rem; }

.sliders { background: white; padding: 16px; border-radius: 12px; border: 1px solid #e2e8f0; margin-bottom: 16px; }
.slider-group { display: flex; align-items: center; gap: 12px; margin-bottom: 12px; }
.slider-group:last-child { margin-bottom: 0; }
.slider-group label { width: 120px; font-size: 0.875rem; color: #334155; }
.slider-group input[type="range"] { flex: 1; height: 6px; -webkit-appearance: none; background: #e2e8f0; border-radius: 3px; }
.slider-group input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none; width: 16px; height: 16px; background: #6366f1; border-radius: 50%; cursor: pointer; }
.test-label { flex: 1; font-size: 0.75rem; color: #94a3b8; }
.color-dot { width: 12px; height: 12px; border-radius: 50%; }
.color-dot.training { background: #3B82F6; }
.color-dot.validation { background: #F59E0B; }
.color-dot.test { background: #10B981; }

.controls { display: flex; gap: 8px; margin-bottom: 16px; }
.controls button { padding: 10px 16px; border: 1px solid #e2e8f0; background: white; border-radius: 8px; cursor: pointer; font-size: 0.875rem; transition: all 0.2s; }
.controls button.primary { background: #6366f1; color: white; border-color: #6366f1; }
.controls button:hover:not(:disabled) { opacity: 0.9; }
.controls button:disabled { opacity: 0.5; cursor: not-allowed; }

.visualization { background: white; border: 1px solid #e2e8f0; border-radius: 12px; padding: 16px; margin-bottom: 16px; }
.data-viz { width: 100%; height: 180px; }

.results { background: white; border: 1px solid #e2e8f0; border-radius: 12px; padding: 16px; margin-bottom: 16px; }
.results h3 { font-size: 0.875rem; color: #334155; margin: 0 0 12px 0; }
.accuracy-bars { display: flex; flex-direction: column; gap: 12px; }
.bar-group { display: flex; align-items: center; gap: 12px; }
.bar-label { width: 140px; font-size: 0.75rem; color: #64748b; }
.bar-container { flex: 1; height: 20px; background: #f1f5f9; border-radius: 10px; overflow: hidden; }
.bar { height: 100%; border-radius: 10px; transition: width 0.8s ease-out; }
.bar.training { background: #3B82F6; }
.bar.validation { background: #F59E0B; }
.bar-value { width: 50px; font-size: 0.75rem; color: #334155; text-align: right; }

.warning { margin-top: 12px; padding: 10px 12px; background: #FEF3C7; border: 1px solid #FCD34D; border-radius: 8px; font-size: 0.8rem; color: #92400E; }

.tips { background: #EEF2FF; border-radius: 12px; padding: 16px; margin-bottom: 16px; }
.tips h3 { font-size: 0.875rem; color: #4338CA; margin: 0 0 8px 0; }
.tips ul { margin: 0; padding-left: 20px; }
.tips li { font-size: 0.8rem; color: #4F46E5; margin-bottom: 4px; }

.reflection { background: #f1f5f9; padding: 16px; border-radius: 12px; }
.reflection h3 { font-size: 0.875rem; color: #334155; margin: 0 0 8px 0; }
.reflection ul { margin: 0; padding-left: 20px; }
.reflection li { font-size: 0.8rem; color: #64748b; margin-bottom: 4px; }
